package cn.codedog.service;
import java.util.*;import org.springframework.stereotype.Service;import org.springframework.jdbc.core.JdbcTemplate;
@Service public class RankingMessageService {
 private final JdbcTemplate j;public RankingMessageService(JdbcTemplate j){this.j=j;}
 public void send(String owner,String kind,String recipient,String key,String title,String body,String target){j.update("INSERT INTO ranking_messages(owner_username,recipient_kind,recipient_id,business_key,title,body,target) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE business_key=business_key",owner,kind,recipient,key,title,body.substring(0,Math.min(500,body.length())),target);}
 public void teacher(String owner,String key,String title,String body,String target){send(owner,"TEACHER",owner,key,title,body,target);}
 public void student(String owner,String student,String key,String title,String body,String target){send(owner,"STUDENT",student,key,title,body,target);}
 public Map<String,Object> list(String owner,String kind,String recipient,int page){int n=Math.max(0,page);return Map.of("items",j.queryForList("SELECT id,title,body,target,created_at,read_at FROM ranking_messages WHERE owner_username=? AND recipient_kind=? AND recipient_id=? ORDER BY id DESC LIMIT 30 OFFSET ?",owner,kind,recipient,n*30L),"page",n,"total",j.queryForObject("SELECT COUNT(*) FROM ranking_messages WHERE owner_username=? AND recipient_kind=? AND recipient_id=?",Long.class,owner,kind,recipient),"unread",j.queryForObject("SELECT COUNT(*) FROM ranking_messages WHERE owner_username=? AND recipient_kind=? AND recipient_id=? AND read_at IS NULL",Long.class,owner,kind,recipient));}
 public void read(String owner,String kind,String recipient,long id){if(j.update("UPDATE ranking_messages SET read_at=COALESCE(read_at,CURRENT_TIMESTAMP(6)) WHERE id=? AND owner_username=? AND recipient_kind=? AND recipient_id=?",id,owner,kind,recipient)!=1)throw RankingPointsService.conflict("消息不存在");}
 public Map<String,Object> alerts(String owner){return Map.of("lowStock",j.queryForList("SELECT r.id,r.reward_name,r.stock,COALESCE(q.low_stock_threshold,3) threshold FROM ranking_rewards r LEFT JOIN ranking_reward_rules q ON q.reward_id=r.id WHERE r.owner_username=? AND r.deleted_at IS NULL AND r.stock<=COALESCE(q.low_stock_threshold,3) ORDER BY r.stock,r.id",owner),"reconciliation",j.queryForList("SELECT c.* FROM ranking_reconciliations c WHERE c.owner_username=? AND c.result='MISMATCH' AND c.id=(SELECT MAX(x.id) FROM ranking_reconciliations x WHERE x.owner_username=c.owner_username AND x.student_id=c.student_id) ORDER BY c.id DESC LIMIT 100",owner),"pendingCancellations",j.queryForObject("SELECT COUNT(*) FROM ranking_reward_redemptions WHERE owner_username=? AND status='CANCEL_REQUESTED'",Long.class,owner),"pendingRecoveries",j.queryForObject("SELECT COUNT(*) FROM ranking_recovery_requests WHERE owner_username=? AND status IN ('PENDING_VERIFY','VERIFIED')",Long.class,owner));}
}
